# -*- coding: utf-8 -*-
"""Phan mo rong ESD cua Module 09 (Tooley Ch.12, tr.197-206): 8 cau goc (khoa A.12 tr.380 doc tu anh quet) + cau bo sung + 2 tu luan -> data/qsrc/m09_esd.json, m09_esd_ess.json.
Bang 12.1 va 12.2 da doc tren anh trang tr.200 va 201. Cau so tinh bang Fraction (verify_m09_esd.py)."""
import os, sys, json
from fractions import Fraction as Fr
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
from qdsl import Bank, OUT
TOP = {'esd': ('Phóng tĩnh điện (ESD) và linh kiện nhạy tĩnh điện', 'Electrostatic discharge (ESD) and static-sensitive devices')}
B = Bank(TOP); T = B.T
T12 = lambda *a, **k: T(12, *a, **k)
T12(1, 'c', 'esd', 1, 'Một vấn đề đặc biệt của sự tích tụ điện tích tĩnh là:', 'A particular problem with the build-up of static charge is that:', [('nó nặng hơn khi ẩm ướt', 'it is worse when wet'), ('nó luôn gây chết người', 'it is invariably lethal'), ('khó phát hiện', 'it cannot easily be detected')], 'Linh kiện có thể hỏng hoàn toàn mà không có dấu hiệu hư hại nhìn thấy; hiệu ứng nặng hơn khi khô (Tooley 12.1).', 'A device can fail totally without any visible sign of damage; the effect is worse when dry (Tooley 12.1).')
T12(2, 'c', 'esd', 1, 'Điện trở điển hình của dây vòng đeo cổ tay (wrist strap) là:', 'The typical resistance of a wrist strap lead is:', [('10 Ω', '10 Ω'), ('1 kΩ', '1 kΩ'), ('1 MΩ', '1 MΩ')], 'Điện trở 1 MΩ nối tiếp hạn chế dòng qua người đeo nếu chạm vật mang điện (Tooley 12.4).', 'A series 1 MΩ resistor limits the current through the wearer if they touch a live conductor (Tooley 12.4).')
T12(3, 'c', 'esd', 1, 'Linh kiện nào sau đây dễ hỏng nhất do điện tích tĩnh?', 'Which one of the following devices is most susceptible to damage from stray static charges:', [('một diode chỉnh lưu công suất', 'a power rectifier'), ('một cổng logic TTL', 'a TTL logic gate'), ('một transistor MOSFET', 'a MOSFET transistor')], 'Linh kiện hiệu ứng trường (MOS) nhạy hơn linh kiện lưỡng cực (Tooley 12.2).', 'Field-effect (MOS) devices are more sensitive than bipolar ones (Tooley 12.2).')
T12(4, 'c', 'esd', 2, 'Điện áp tĩnh sinh ra khi một người đi trên thảm có thể:', 'The static voltage generated when a person walks across a carpet can be:', [('không quá khoảng 10 kV', 'no more than about 10 kV'), ('giữa 10 kV và 20 kV', 'between 10 kV and 20 kV'), ('hơn 20 kV', 'more than 20 kV')], 'Bảng 12.1: 35 kV ở độ ẩm 20 %.', 'Table 12.1: 35 kV at 20 % relative humidity.')
T12(5, 'c', 'esd', 1, 'Vật liệu nào sau đây mang điện ÂM trên thang tĩnh điện ma sát (triboelectric)?', 'Which of the materials listed is negative on the triboelectric scale:', [('thuỷ tinh', 'glass'), ('lụa', 'silk'), ('polyester', 'polyester')], 'Thuỷ tinh và lụa thuộc phía dương; polyester thuộc phía âm (Tooley 12.1.1).', 'Glass and silk are on the positive side; polyester is on the negative side (Tooley 12.1.1).')
T12(6, 'a', 'esd', 1, 'Khi vận chuyển linh kiện nhạy tĩnh điện (ESD) điều quan trọng là:', 'When transporting ESDs it is important to:', [('để trong bao bì dẫn điện', 'keep them in a conductive package'), ('lấy ra và bọc trong lá kim loại', 'remove them and place them in metal foil'), ('đặt trong bao bì nhựa cách điện', 'place them in an insulated plastic package')], 'Vật liệu dẫn điện bảo vệ tốt nhất; chống tĩnh điện kém nhất (Tooley 12.4).', 'Conductive materials protect best; anti-static ones least (Tooley 12.4).')
T12(7, 'a', 'esd', 1, 'Để giảm nguy cơ hỏng linh kiện ESD khi hàn, điều quan trọng là:', 'To reduce the risk of damaging an ESD during soldering it is important to:', [('chỉ dùng mỏ hàn điện áp thấp', 'use only a low-voltage soldering iron'), ('chỉ dùng mỏ hàn chạy điện lưới', 'use only a mains-operated soldering iron'), ('chỉ dùng mỏ hàn nhiệt độ thấp', 'use only a low-temperature soldering iron')], 'Dùng mỏ hàn điện áp thấp có đầu nối đất (trạm hàn chống tĩnh điện) (Tooley 12.4).', 'Use low-voltage irons with grounded bits (anti-static soldering stations) (Tooley 12.4).')
T12(8, 'a', 'esd', 1, 'Loại quần áo nào có khả năng gây vấn đề tĩnh điện nhiều nhất?', 'Which one of the following items of clothing is most likely to cause static problems:', [('áo yếm nylon', 'nylon overalls'), ('áo thun cotton', 'a cotton T-shirt'), ('quần polyester pha cotton', 'polyester-cotton trousers')], 'Vật liệu tổng hợp dễ nhiễm điện; cotton trung tính (Tooley 12.1.1).', 'Man-made materials charge easily; cotton is neutral (Tooley 12.1.1).')
X = B.X
T121 = [('đi trên thảm len/nylon', 'walking over a wool/nylon carpet', 35e3, 1.5e3), ('trượt hộp nhựa trên thảm', 'sliding a plastic box across a carpet', 18e3, 1.2e3), ('lấy linh kiện ra khỏi túi polystyrene', 'removing parts from a polystyrene bag', 15e3, 1e3), ('đi trên sàn vinyl', 'walking over vinyl flooring', 11e3, 350), ('bóc màng co', 'removing shrink-wrap packaging', 10e3, 250), ('làm việc ở bàn mặc áo yếm', 'working at a bench wearing overalls', 8e3, 150)]
def fv(v): return f'{v / 1e3:g} kV' if v >= 1e3 else f'{v:g} V'
for vi, en, hi, lo in T121[:4]:
    r = hi / lo; X('esd', 2, f'Theo Bảng 12.1, khi {vi} điện áp tĩnh ở độ ẩm 20 % lớn hơn ở độ ẩm 80 % bao nhiêu lần (xấp xỉ)?', f'By Table 12.1, when {en} how many times larger is the static voltage at 20 % relative humidity than at 80 % (approximately)?', [f'{r:.0f}', f'{r / 2:.0f}', f'{r * 2:.0f}', '4'], 0, f'{fv(hi)} / {fv(lo)} = {r:.1f} lần: không khí khô làm điện tích tích tụ nhiều hơn rất nhiều.', f'{fv(hi)} / {fv(lo)} = {r:.1f} times: dry air lets far more charge build up.', 'Độ ẩm và điện áp tĩnh', 'Humidity and static voltage')
X('esd', 2, 'Theo Bảng 12.1 tình huống nào sinh điện áp tĩnh LỚN NHẤT ở độ ẩm tương đối 20 %?', 'By Table 12.1 which situation generates the LARGEST static voltage at 20 % relative humidity?', [('đi trên thảm len/nylon (35 kV)', 'walking over a wool/nylon carpet (35 kV)'), ('đi trên sàn vinyl (11 kV)', 'walking over vinyl flooring (11 kV)'), ('bóc màng co (10 kV)', 'removing shrink-wrap packaging (10 kV)'), ('làm việc ở bàn mặc áo yếm (8 kV)', 'working at a bench wearing overalls (8 kV)')], 0, 'Tooley Bảng 12.1.', 'Tooley Table 12.1.', 'Bảng 12.1', 'Table 12.1')
T122 = [('bộ nhớ động', 'dynamic memories', 20, 100), ('vi xử lý VLSI', 'VLSI microprocessors', 20, 100), ('MOSFET', 'MOSFETs', 50, 350), ('transistor lưỡng cực (BJT)', 'bipolar junction transistors', 150, 5000), ('logic CMOS', 'CMOS logic', 250, 1000), ('điện trở màng mỏng', 'thin-film resistors', 300, 3000), ('logic TTL', 'TTL logic', 550, 2500), ('chỉnh lưu có điều khiển (SCR)', 'silicon-controlled rectifiers', 4000, 15000)]
X('esd', 2, 'Theo Bảng 12.2, loại linh kiện nào nhạy với điện áp tĩnh nhất (ngưỡng thấp nhất, 20 V)?', 'By Table 12.2, which kind of device is the most sensitive to static voltage (lowest threshold, 20 V)?', [('bộ nhớ động và vi xử lý VLSI', 'dynamic memories and VLSI microprocessors'), ('logic TTL', 'TTL logic'), ('chỉnh lưu có điều khiển (SCR)', 'silicon-controlled rectifiers'), ('transistor lưỡng cực', 'bipolar junction transistors')], 0, 'Ngưỡng 20 V đến 100 V.', 'Threshold 20 V to 100 V.', 'Bảng 12.2', 'Table 12.2')
X('esd', 2, 'Theo Bảng 12.2, loại linh kiện nào ÍT nhạy nhất (ngưỡng cao nhất)?', 'By Table 12.2, which kind of device is the LEAST sensitive (highest threshold)?', [('chỉnh lưu có điều khiển (SCR), 4 đến 15 kV', 'silicon-controlled rectifiers, 4 to 15 kV'), ('logic CMOS, 250 V đến 1 kV', 'CMOS logic, 250 V to 1 kV'), ('MOSFET, 50 đến 350 V', 'MOSFETs, 50 to 350 V'), ('logic TTL, 550 V đến 2,5 kV', 'TTL logic, 550 V to 2.5 kV')], 0, 'SCR chịu được tới 15 kV; Tooley TYU 12.3 hỏi linh kiện nhạy nhất trong ba: bộ nhớ động, SCR, BJT.', 'The SCR tolerates up to 15 kV; Tooley TYU 12.3 asks for the most sensitive of three: dynamic memory, SCR, BJT.', 'Bảng 12.2', 'Table 12.2')
for lo, hi, vi_, en_ in ((20, 100, 'bộ nhớ động', 'dynamic memory'), (250, 1000, 'logic CMOS', 'CMOS logic')):
    X('esd', 3, f'Một {vi_} có ngưỡng nhạy tĩnh điện từ {fv(lo)} đến {fv(hi)} (Bảng 12.2). Một người mang điện áp tĩnh 1,5 kV chạm vào nó. So với khoảng nhạy thì:', f'A {en_} has a static susceptibility range of {fv(lo)} to {fv(hi)} (Table 12.2). A person carrying 1.5 kV of static touches it. Compared with that range the voltage is:', ['gấp nhiều lần ngưỡng cao nhất của khoảng, rất dễ làm hỏng' if hi < 1500 else 'trên ngưỡng cao nhất của khoảng', 'dưới ngưỡng thấp nhất của khoảng, an toàn', 'nằm giữa khoảng, không chắc gây hỏng'][:3] if False else ([('cao hơn ngưỡng trên của khoảng: có thể gây hỏng', 'above the top of the range: damage is possible'), ('thấp hơn ngưỡng dưới: chắc chắn an toàn', 'below the bottom of the range: certainly safe'), ('bằng đúng ngưỡng giữa', 'exactly at the midpoint')] if hi < 1500 else [('trong khoảng hoặc trên ngưỡng dưới: có thể gây hỏng', 'inside or above the bottom of the range: damage is possible'), ('thấp hơn ngưỡng dưới: chắc chắn an toàn', 'below the bottom of the range: certainly safe'), ('thấp hơn nhiều so với ngưỡng: vô hại', 'far below the range: harmless')]), 0,
      f'1,5 kV so với khoảng {fv(lo)} đến {fv(hi)}: ' + ('lớn hơn cả ngưỡng trên' if hi < 1500 else 'nằm trên ngưỡng dưới (và trên ngưỡng trên)') + '; điện tích mà người mang thường vượt xa ngưỡng này.', f'1.5 kV against {fv(lo)} to {fv(hi)}: ' + ('above even the top' if hi < 1500 else 'above the bottom (and above the top)') + '; the charge a person carries easily exceeds such thresholds.', 'So sánh với ngưỡng nhạy', 'Comparison with susceptibility')
for V in (115, 230):
    I = Fr(V) / 1_000_000 * 1000
    X('esd', 3, f'Dây vòng cổ tay có điện trở nối tiếp 1 MΩ. Nếu người đeo chạm nhầm vào vật mang {V} V (minh hoạ, bỏ qua điện trở cơ thể), dòng điện giới hạn tối đa là:', f'A wrist-strap lead has a 1 MΩ series resistor. If the wearer touches a conductor at {V} V by mistake (illustration, ignoring body resistance) the maximum current is limited to:', [f'{float(I):g} mA', f'{float(I * 1000):g} mA', f'{float(I / 1000):g} mA', f'{float(I * 10):g} mA'], 0, f'$I=V/R={V}/10^6$ A = {float(I):g} mA.', f'$I=V/R={V}/10^6$ A = {float(I):g} mA.', 'Điện trở 1 MΩ của dây đeo tay', '1 MΩ wrist strap resistor')
X('esd', 1, 'Trên thang tĩnh điện ma sát (triboelectric), cặp vật liệu nào cho lượng điện tích cảm ứng LỚN nhất khi cọ xát?', 'On the triboelectric scale, which pair of materials gives the LARGEST induced charge when rubbed together?', [('PVC và thuỷ tinh (hai đầu mút của thang)', 'PVC and glass (the extreme ends of the scale)'), ('bông và thép (cả hai trung tính)', 'cotton and steel (both neutral)'), ('lụa và thuỷ tinh (cùng phía dương)', 'silk and glass (same positive side)')], 0, 'Tooley 12.1.1: vật liệu ở hai đầu mút của thang cọ vào nhau cho điện tích lớn nhất.', 'Tooley 12.1.1: materials at the extreme ends of the scale rubbed together give the largest charge.', 'Thang triboelectric', 'Triboelectric series')
X('esd', 2, 'Vật liệu nào trung tính trên thang triboelectric và vì vậy nên mặc khi làm việc trong môi trường khô?', 'Which material is neutral on the triboelectric scale and so is advised for clothing in dry conditions?', [('bông (cotton)', 'cotton'), ('polyester', 'polyester'), ('nylon', 'nylon'), ('Teflon', 'Teflon')], 0, 'Thép cũng trung tính; Teflon là âm nhất (Tooley 12.1.1).', 'Steel is also neutral; Teflon is the most negative (Tooley 12.1.1).', 'Vật liệu trung tính', 'Neutral materials')
X('esd', 2, 'Linh kiện nhạy tĩnh điện thường được dán nhãn cảnh báo như thế nào?', 'How are static-sensitive components usually marked with warnings?', [('chữ đen trên nền vàng', 'black text on a yellow background'), ('chữ trắng trên nền đỏ', 'white text on a red background'), ('chữ xanh trên nền trắng', 'blue text on a white background')], 0, 'Tooley 12.3.', 'Tooley 12.3.', 'Nhãn cảnh báo ESD', 'ESD warning labels')
X('esd', 2, 'Vì sao linh kiện lắp trên bảng mạch in ít bị nguy cơ hơn linh kiện rời?', 'Why are components mounted on a printed circuit board at less risk than loose ones?', [('các đường dẫn trên mạch in giúp xả điện tích dư', 'the conductive paths of the printed circuit help dissipate excess charge'), ('mạch in cách điện hoàn toàn', 'the printed circuit is a perfect insulator'), ('linh kiện trên mạch in không phải là bán dẫn', 'components on a board are not semiconductors')], 0, 'Linh kiện rời không có đường xả tĩnh điện (Tooley 12.2).', 'A loose device has no static dissipative path (Tooley 12.2).', 'Mạch in và ESD', 'PCB and ESD')
X('esd', 2, 'Trong ba loại vật liệu bảo vệ linh kiện nhạy tĩnh điện, loại nào bảo vệ NHIỀU nhất và ít nhất?', 'Of the three classes of materials protecting static-sensitive devices, which protects MOST and which LEAST?', [('dẫn điện nhiều nhất; chống tĩnh điện (trung tính) ít nhất', 'conductive most; anti-static (neutral) least'), ('chống tĩnh điện nhiều nhất; dẫn điện ít nhất', 'anti-static most; conductive least'), ('tiêu tán tĩnh điện nhiều nhất; dẫn điện ít nhất', 'static dissipative most; conductive least')], 0, 'Dẫn điện (lá kim loại, vật liệu tẩm cacbon), tiêu tán tĩnh điện (rẻ hơn), chống tĩnh điện (bìa, bông, gỗ) (Tooley 12.4).', 'Conductive (metal foils, carbon-impregnated plastics), static dissipative (cheaper), anti-static (cardboard, cotton, wood) (Tooley 12.4).', 'Vật liệu bảo vệ', 'Protective materials')
X('esd', 1, 'Điều nào sau đây là biện pháp xử lý ESD đúng theo Tooley 12.4?', 'Which of the following is a correct ESD handling measure according to Tooley 12.4?', [('đeo vòng cổ tay nối đất và để linh kiện trong bao bì chống tĩnh điện cho tới khi dùng', 'wear a grounded wrist strap and keep parts in their anti-static packaging until needed'), ('làm việc gần đèn huỳnh quang điện áp cao', 'work next to high-voltage fluorescent lights'), ('cầm linh kiện trần ở nơi rất khô', 'handle bare parts in a very dry place')], 0, 'Còn gồm: dây đeo gót, thảm sàn và bàn tiêu tán tĩnh điện, tránh nơi quá khô, ổ nối đất, thiết bị thử nối đất, mỏ hàn điện áp thấp, dụng cụ cắm/rút IC chống tĩnh điện, tránh nguồn cao áp lân cận.', 'Also: heel straps, static-dissipative floor and bench mats, avoiding very dry places, ground jacks, grounded test equipment, low-voltage soldering, anti-static IC tools, avoiding nearby high-voltage sources.', 'Biện pháp xử lý ESD', 'ESD handling measures')
B.E('esd', 2, 'Trình bày bảy việc cần làm để xử lý và vận chuyển linh kiện nhạy tĩnh điện, và nêu vì sao một người đi trên thảm len/nylon có thể làm hỏng một vi xử lý VLSI. Dùng số liệu Bảng 12.1 và 12.2.', 'State seven things to do when handling and transporting static-sensitive devices, and explain why a person walking over a wool/nylon carpet can damage a VLSI microprocessor. Use the numbers of Tables 12.1 and 12.2.',
  'Bảy việc: vòng cổ tay có điện trở 1 MΩ nối đất; dây đeo gót; thảm sàn và bàn tiêu tán tĩnh điện; tránh môi trường quá khô; ổ nối đất; thiết bị thử nối đất; mỏ hàn điện áp thấp nối đất (còn: dụng cụ IC chống tĩnh điện, tránh nguồn cao áp, bao bì chống tĩnh điện). Đi trên thảm len/nylon ở độ ẩm 20 % sinh tới 35 kV (Bảng 12.1) trong khi vi xử lý VLSI chỉ chịu 20 V đến 100 V (Bảng 12.2): gấp ít nhất 350 lần ngưỡng cao nhất; ở độ ẩm 80 % vẫn có 1,5 kV, vẫn gấp 15 lần.', 'Seven things: a grounded wrist strap with a 1 MΩ resistor; heel straps; static-dissipative floor and bench mats; avoiding very dry environments; ground jacks; grounded test equipment; low-voltage grounded soldering irons (also anti-static IC tools, avoiding high-voltage sources, anti-static packaging). Walking over a wool/nylon carpet at 20 % humidity generates up to 35 kV (Table 12.1) while a VLSI microprocessor withstands only 20 V to 100 V (Table 12.2): at least 350 times the top of its range; at 80 % humidity it is still 1.5 kV, still 15 times.', 'Xử lý ESD', 'ESD handling')
B.E('esd', 3, 'Một bộ nhớ động có ngưỡng 20 V đến 100 V. (a) Một người ở bàn làm việc mặc áo yếm sinh 8 kV ở độ ẩm 20 % và 150 V ở 80 %: so với ngưỡng trên 100 V mỗi trường hợp gấp bao nhiêu lần? (b) Nếu cùng người đó đeo vòng cổ tay 1 MΩ và chạm vào vật 230 V thì dòng giới hạn là bao nhiêu? (c) Điều này nói gì về ESD ở nơi ẩm và khô?', 'A dynamic memory has a threshold of 20 V to 100 V. (a) A person at a bench in overalls generates 8 kV at 20 % humidity and 150 V at 80 %: how many times the 100 V upper threshold is each? (b) If the same person wears a 1 MΩ wrist strap and touches a 230 V conductor, what is the limited current? (c) What does this say about ESD in humid and dry places?',
  f'(a) 8 000 / 100 = {8000 / 100:.0f} lần; 150 / 100 = {150 / 100:.1f} lần (vẫn vượt ngưỡng!). (b) $I=230/10^6$ A = {230 / 1e6 * 1000:.2f} mA. (c) Không khí ẩm giảm điện áp tĩnh hàng chục lần nhưng với linh kiện nhạy nhất (20 V đến 100 V) cũng chưa đủ an toàn, nên vẫn phải dùng vòng cổ tay và bao bì chống tĩnh điện.', f'(a) 8,000 / 100 = {8000 / 100:.0f} times; 150 / 100 = {150 / 100:.1f} times (still above the threshold!). (b) $I=230/10^6$ A = {230 / 1e6 * 1000:.2f} mA. (c) Humid air cuts the static voltage tens of times but for the most sensitive devices (20 V to 100 V) it is still not safe, so a wrist strap and anti-static packaging are always needed.', 'Tính toán ESD', 'ESD calculation')
if __name__ == '__main__':
    import collections
    json.dump(B.goc + B.gen, open(os.path.join(OUT, 'm09_esd.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    json.dump(B.ess, open(os.path.join(OUT, 'm09_esd_ess.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print('m09 ESD goc', len(B.goc), 'gen', len(B.gen), 'ess', len(B.ess), dict(collections.Counter(i['level'] for i in B.goc + B.gen)))
